@import 'c/rlySharedStyles';

.rr-rs { background: #fff; border: 1px solid #e5e5e5; border-radius: 4px; box-shadow: 0 2px 2px rgba(0, 0, 0, 0.05); padding: 12px 14px; display: flex; flex-direction: column; gap: 10px; margin-bottom: 12px; }
.rr-rs-head { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.rr-grow { flex: 1 1 auto; min-width: 0; }
.rr-weak { color: #5c5c5c; }
.rr-mono { font-family: Menlo, Consolas, monospace; font-size: 12px; }
.rr-break { overflow-wrap: anywhere; }
.rr-facts { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 8px 14px; margin: 0; }
.rr-facts dt { font-size: 12px; color: #5c5c5c; }
.rr-facts dd { margin: 0; font-size: 13px; }
.rr-new { display: flex; flex-direction: column; gap: 10px; border: 1px solid #e5e5e5; border-radius: 4px; padding: 10px 12px; background: #fafaf9; }
.rr-key { background: #fff; border: 1px dashed #a0a0a0; border-radius: 4px; padding: 8px 10px; font-family: Menlo, Consolas, monospace; font-size: 13px; overflow-wrap: anywhere; user-select: all; }
.rr-steps { margin: 0; padding-left: 18px; font-size: 12.5px; }
.rr-steps li { margin: 3px 0; }
.rr-actions { display: flex; gap: 8px; justify-content: flex-end; flex-wrap: wrap; }
.rr-pill { display: inline-block; font-size: 11px; font-weight: 700; padding: 2px 9px; border-radius: 10px; white-space: nowrap; }
.rr-pill-bad { background: #feded8; color: #ba0517; }
.rr-pill-wait { background: #fef1cd; color: #a96404; }
.rr-pill-none { background: #f3f3f3; color: #5c5c5c; }
.rr-table { border: 1px solid #e5e5e5; border-radius: 4px; overflow-x: auto; }
.rr-tr { display: grid; grid-template-columns: 22px minmax(180px, 1.2fr) minmax(200px, 1.6fr); gap: 10px; align-items: start; padding: 8px 10px; border-bottom: 1px solid #f1f1f1; font-size: 12.5px; }
.rr-tr:last-child { border-bottom: 0; }
.rr-ic { width: 18px; height: 18px; border-radius: 50%; display: inline-flex; align-items: center; justify-content: center; font-size: 11px; font-weight: 700; color: #fff; }
.rr-ic-ok { background: #2e844a; }
.rr-ic-missing { background: #ba0517; }
.rr-ic-unknown { background: #9a9a9a; }
.rr-pb { padding-bottom: 4px; }
